        int best = 0;
        for (int i = 0; i < r; i++) {
            String row = br.readLine().trim();
            int[] cur = new int[c + 1];
            for (int j = 1; j <= c; j++) {
                if (row.charAt(j - 1) == '1') {
                    cur[j] = 1 + Math.min(prev[j], Math.min(cur[j - 1], prev[j - 1]));
                    best = Math.max(best, cur[j]);
                }
            }
            prev = cur;
        }
        System.out.println(best);
    }
}

